  const v = blend*0.5+0.5;
  const pal = [[5,10,45],[10,30,80],[12,60,105],[18,100,130],[30,150,140],[80,175,120],[180,190,80],[220,170,60],[230,130,65],[210,85,60],[180,50,55],[120,25,50],[60,12,40],[5,10,45]];
